// Book catalog + chapter structure, captured from the live site 2026-10-14.
//
// CHAPTER TEXT IS SERVED BY THE SERVER (since Oct 27, 2026): the reader
// fetches each chapter from /api/books/:id/chapters/:n — free chapters
// publicly, paid chapters only for entitled accounts. The `text` fields
// below are legacy placeholder slots and are NOT used for delivery; real
// manuscript text lives server-side only (server/src/content-data.ts,
// generated by scripts/build-content.mjs) so it can never be lifted from
// this bundle. Do NOT paste manuscript text in here.
export const MANUSCRIPT_PLACEHOLDER = "CONTENT FROM MANUSCRIPT — TO BE INSERTED";

export interface Chapter {
  /** Sidebar label, e.g. "Prologue" or "Chapter One". */
  label: string;
  /** Optional captured chapter title (Trust has titles; Doors does not). */
  title?: string;
  free: boolean;
  text: string;
}

export interface Book {
  id: "doors1" | "trust" | "quietlyready";
  bookPath: string;
  readerPath: string;
  genre: string;
  title: string;
  tagline: string;
  blurb: string;
  chaptersLabel: string;
  wordsLabel: string;
  priceLabel: string;
  priceCents: number;
  /** Book-page label for the free-opening button. */
  freeLabel: string;
  /** Optional cover image (public path). Books without one use the icon tile. */
  coverSrc?: string;
  chapters: Chapter[];
}

const ch = (label: string, free: boolean, title?: string): Chapter => ({
  label,
  title,
  free,
  text: MANUSCRIPT_PLACEHOLDER,
});

const DOORS_NUMBERS = [
  "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine",
  "Ten", "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen",
  "Seventeen",
];

